export const postApiV4RolloutsId = os
  .route({
    method: 'POST',
    path: '/api/v4/rollouts/{id}',
    tags: ['Rollouts'],
    summary: 'Ingest a rollout workflow event',
    description:
      'Reports flow-graph progress from the CD orchestrator (a Starlark workflow run by AutoFlow).',
    successStatus: 202,
    successDescription: 'Accepted',
  })
  .input(
    type({
      id: type('string').pipe((data, ctx) => {
        const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
        return Number.isSafeInteger(value) ? value : ctx.error('an integer')
      }),
      'topic?': type('string | null').describe('The event topic'),
      'type?': type(
        type('string').narrow(
          (data, ctx) => [...data].length <= 255 || ctx.mustBe('at most 255 characters'),
        ),
      )
        .or('null')
        .describe('The event type'),
      'data?': type(
        type({
          'position?': type('number.integer[] | null').describe(
            'Zero-based path to the stage/step in the flow definition; required for every event except com.gitlab.cd.rollout_succeeded',
          ),
          'stage_name?': type(
            type('string').narrow(
              (data, ctx) => [...data].length <= 255 || ctx.mustBe('at most 255 characters'),
            ),
          )
            .or('null')
            .describe(
              'Name of the enclosing stage (an environment tier); absent for a step outside any stage',
            ),
          'environment?': type(
            type('string').narrow(
              (data, ctx) => [...data].length <= 255 || ctx.mustBe('at most 255 characters'),
            ),
          )
            .or('null')
            .describe(
              'Exact name of the target GitLab environment; resolves the rollout environment to update when a stage deploys to more than one environment',
            ),
          'step_type?': type(
            type('string').narrow(
              (data, ctx) => [...data].length <= 255 || ctx.mustBe('at most 255 characters'),
            ),
          )
            .or('null')
            .describe('The step type, present on step_* events'),
          'service?': type(
            type('string').narrow(
              (data, ctx) => [...data].length <= 255 || ctx.mustBe('at most 255 characters'),
            ),
          )
            .or('null')
            .describe(
              'Name of the Cd::Service, present on service_started/service_succeeded/service_failed',
            ),
          'error?': type(
            type('string').narrow(
              (data, ctx) => [...data].length <= 2000 || ctx.mustBe('at most 2000 characters'),
            ),
          )
            .or('null')
            .describe('Failure detail, present on step_failed and service_failed'),
          'reason?': type(
            type('string').narrow(
              (data, ctx) => [...data].length <= 2000 || ctx.mustBe('at most 2000 characters'),
            ),
          )
            .or('null')
            .describe('Human-readable prompt, present on approval_requested'),
          'reply?': type(
            type('string').narrow(
              (data, ctx) => [...data].length <= 255 || ctx.mustBe('at most 255 characters'),
            ),
          )
            .or('null')
            .describe(
              'Name of the AutoFlow channel to post the approval decision back into, present on approval_requested',
            ),
        }),
      )
        .or('null')
        .describe('The event payload. Exactly one of `data`, `value` must be provided.'),
      'value?': type(type({}))
        .or('null')
        .describe(
          'AutoFlow Value (protojson), decoded into the same topic/type/data shape as `data` above. Exactly one of `data`, `value` must be provided.',
        ),
      'channel_tokens?': type(
        type(
          type({
            channel_name: type(
              type('string').narrow(
                (data, ctx) => [...data].length <= 255 || ctx.mustBe('at most 255 characters'),
              ),
            )
              .or('null')
              .describe('Name of the AutoFlow channel'),
            token: type(
              type('string').narrow(
                (data, ctx) => [...data].length <= 4096 || ctx.mustBe('at most 4096 characters'),
              ),
            )
              .or('null')
              .describe('Token used to post a value into the channel'),
          }),
        ).array(),
      )
        .or('null')
        .describe(
          'AutoFlow channels opened alongside this event, for posting a value back into them later',
        ),
    }),
  )
  .output(APIEntitiesCdRolloutSchema)
  .handler(async ({ input }) => { throw new Error('Not implemented') })

export const postApiV4OrbitQuery = os
  .route({
    method: 'POST',
    path: '/api/v4/orbit/query',
    tags: ['Orbit'],
    summary: 'Execute a query',
    description:
      'Executes a query against the Orbit gRPC service. For `response_format` `llm` and `gql`, the response is `text/plain`.',
  })
  .input(PostApiV4OrbitQueryRequestSchema)
  .output(OrbitQueryResponseSchema)
  .handler(async ({ input }) => { throw new Error('Not implemented') })

export const postApiV4OrbitQueryName = os
  .route({
    method: 'POST',
    path: '/api/v4/orbit/query/{name}',
    tags: ['Orbit'],
    summary: 'Execute a named query',
    description:
      'Executes a server-defined named query against the Orbit gRPC service. Orbit defines its named queries on the server, so they stay in step with the query language and the schema. For programmatic use, this endpoint is preferred over `POST /orbit/query`. The GraphQL field `Query.orbit.queryTemplates` lists the named queries. Each query template has a `name`, a `description`, and the GQL `query` it runs. The `name` of a query template is passed as `:name` in the path. Requires a JSON request body: form encoding stringifies nested parameter values, which the per-query parameter schemas reject. This endpoint can return the same errors as `POST /orbit/query`.',
  })
  .input(
    type({
      name: type('string'),
      'parameters?': type(type({})).or('null').describe('Named query parameters'),
      'response_format?': type("'raw' | 'llm' | 'gql' | null").describe(
        'Response format: raw, llm, or gql',
      ),
      'source_type?': type('string | null').describe(
        'Subtype of a request from the GitLab UI. Only `code_intelligence` has an effect. The API ignores the attribute for requests that do not come from a GitLab UI session.',
      ),
    }),
  )
  .output(OrbitQueryResponseSchema)
  .handler(async ({ input }) => { throw new Error('Not implemented') })

export const postApiV4OrbitContext = os
  .route({
    method: 'POST',
    path: '/api/v4/orbit/context',
    tags: ['Orbit'],
    summary: 'Get entity context',
    description:
      'Resolves one Orbit token to a PostgreSQL summary and, optionally, its graph neighborhood. The entity can be a merge request, work item, CI/CD job, CI/CD pipeline, branch, or commit. Requests that reach token resolution count against the orbit_query rate limit; with expand, they run at most one billable graph query. Requires a JSON request body. The request and response shape can change without notice. A `tokens` array that does not hold exactly one string, or an `expand` value that is not the JSON boolean `true` or `false`, returns `400 Bad Request`. With a fine-grained personal access token, the `read_orbit` permission is not enough. The token also needs `read_merge_request` or `read_work_item` on the project or group of the entity, `read_job` on the project for a job and for job logs, `read_pipeline` for pipelines, `read_pipeline_test_report` for failed tests, `read_pipeline_job` for pipeline jobs, `read_branch` or `read_commit` for a branch or commit, `read_commit_diff` and `read_commit_merge_request` for the changed files and merge requests of a commit, and `download_code` for the changed files of a merge request. Without them, the entity is returned as `not_found`. The pipeline status is `null`, and linked items the token cannot read are left out of the summary. Discussions need `read_merge_request_discussion` for a merge request, `read_epic_discussion` for an epic, and `read_issue_discussion` for other work items. Without them, `discussions` is `null`. The project scope of the token applies to the entity summary only. The graph expansion is filtered by the access of the user, the same as for named queries. Token forms are: `Type[id]`, for example `MergeRequest[123]`, where `id` is the global database ID; `gid://gitlab/<Type>/<id>`; a merge request, issue, work item, job, pipeline, or commit URL on this instance, including group work item URLs under `/groups/`; `path!iid` for a merge request, for example `gitlab-org/gitlab!42`; `path#iid` for a work item, for example `gitlab-org/gitlab#7`, where the path can also be a group; `Epic[id]`, `gid://gitlab/Epic/<id>`, an epic URL such as `/groups/gitlab-org/-/epics/5`, or `group&iid`, for example `gitlab-org&5`, where `id` is the epic ID; and `path@ref` for a branch of the project at `path`, or for a commit SHA when no branch has that name, for example `gitlab-org/gitlab@main`. The supported types are `MergeRequest`, `WorkItem`, `Job`, `Pipeline`, `Branch`, and `Commit`. `Issue` is an alias for `WorkItem`, and the response reports `WorkItem`. An epic resolves to its work item in the same way: the response reports `WorkItem`, the ID of the work item, and `work_item_type` `epic`, and the expansion runs for the work item. Other types return `unsupported_type`. Summaries include these fields. For a merge request: title, state, author, branches, head pipeline status, merge commit, reviewers, linked issues, description, changed files with their diffs, failed jobs, and discussions. For a work item: title, state, labels, assignees, milestone, linked merge requests, description, and discussions. For a job: name, status, stage, failure reason, ref, commit, pipeline, merge request, failed tests, and log. For a pipeline: status, ref, commit, source, merge request, jobs, and failed jobs. Jobs come from the pipeline itself, not from its child pipelines. For a branch: head commit, its open or latest merge request, and its latest pipeline with failed jobs. For a commit: title, description, author, its latest pipeline, the merge requests that contain it, and changed files. Failed tests come from the unit test report of the job. The log of a job is its job script output, followed by its `after_script` output, with lines longer than 500 characters cut. The log has a size limit of 40 KB for a requested job and 6 KB for each failed job of a merge request, pipeline, or branch, and `after_script` output gets at most a quarter of it. When a part does not fit, runs of five or more lines that differ only in numbers or hashes, such as progress output, are folded into their first and last line, and only the end of that part that fits is kept. `...` marks where lines were left out, and for a requested job `summary.truncated` then includes `log`. Changed line ranges use new-file line numbers, so a deletion is reported at the line after it, which can be one past the end of the file. A changed file has no `lines` when it was deleted or its diff could not be read, and empty `lines` when its diff has no text lines, such as for a binary or very large file. The `diff` of a changed file has its first 40 diff lines, with 200 lines shared across the merge request in file order. It is absent for deleted, generated, binary, and very large files, and for files after the budget ran out. A cut diff ends with `... N more diff lines`, and `summary.truncated` then includes `diffs`. Lists are limited and contain only records the user can read. `summary.truncated` is an array with the names of the lists that were cut, for example `["reviewers"]`. It is empty when no list was cut. A failed job of a merge request whose failed tests were cut has `truncated: ["failed_tests"]`. Entries in `linked_issues` and `linked_merge_requests` are ordered by ID and have `type`, `id` (a string), `token`, `relation` (`CLOSES`), `iid`, `project_path`, and `title`. Every failure after a lookup starts returns the same `not_found` error, whether the record is missing or the user cannot read it. With `expand`, the request runs at most one graph query, using the `context_for_review`, `context_for_issue`, or `context_for_job` named query. Other types return `expansion_unsupported_type`. A request that runs one query is billed as one query. A failure of the expansion never fails the summary. `expansion.query` has the `name` and `parameters` of the query. It is present on a result and on every error except `expansion_unsupported_type`, including when no query ran. After `outside_graph_scope`, a rerun is billed and returns nothing. `expansion.error.code` is one of: `expansion_unsupported_type`, when the type has no expansion query; `outside_graph_scope`, when the entity is outside the part of the graph the user can query, which is a group where the user is not at least a Reporter or a group where Orbit is not turned on, and no query runs and nothing is billed; `billing_namespace_required`, with `message`, `deep_link` to the preferences of the user, and `candidates`, the groups the user can select, matching the `422` response of `POST /api/v4/orbit/query/:name`; or `quota_exhausted`, `timeout`, or `execution_error`. If `pagination.truncated` in the graph result is `false`, a missing center node means the entity has no readable neighbors. Otherwise, the result is unknown. With `response_format=llm`, the response is `text/plain`. Each entity starts with its scalar fields, then its graph in TOON format under an indented `graph:` label, before longer blocks such as the description. A graph with no nodes is left out, and a failed expansion is a single `graph_error=<code>` line. When a list in an entity is cut, the entity includes a `truncated=` line right after its scalar fields that names the incomplete lists, for example `truncated=reviewers,changed_files`. A failed job whose failed tests were cut has its own `truncated=failed_tests` line. This feature was introduced in GitLab 19.6.',
  })
  .input(PostApiV4OrbitContextRequestSchema)
  .output(APIEntitiesOrbitContextSchema)
  .handler(async ({ input }) => { throw new Error('Not implemented') })

