export const patchApiV4ProjectsIdComplianceExternalControlsControlIdStatus = os
  .route({
    method: 'PATCH',
    path: '/api/v4/projects/{id}/compliance_external_controls/{control_id}/status',
    tags: ['Compliance policy settings'],
    summary: 'Set status of an external control',
    description:
      'Sets the status of a specified external control. Use this operation to inform GitLab that a control has\npassed, failed, or does not apply to the project. Controls with the `not_applicable` status do not count as\npassed or failed.\n\nRequests must use HMAC, timestamp, and nonce authentication, with these headers:\n\n| Header | Required | Description |\n|--------|----------|-------------|\n| `X-Gitlab-Timestamp` | Yes | Current Unix timestamp. Requests 15 seconds old or older are rejected. |\n| `X-Gitlab-Nonce` | Yes | Random string of exactly 32 characters, to prevent replay attacks. |\n| `X-Gitlab-Hmac-Sha256` | Yes | HMAC-SHA256 signature of the request. |\n\nTo compute the HMAC-SHA256 signature:\n\n1. Concatenate these values in this order: the `X-Gitlab-Timestamp` value, the `X-Gitlab-Nonce` value,\n   the entire path of the request, and the `status` value formatted as `status=<status>`.\n1. Compute the HMAC-SHA256 of the concatenated string with your secret key.\n\nThis feature was introduced in GitLab 17.11.\n',
  })
  .input(
    type({
      id: type('unknown').pipe((data, ctx) => {
        for (const branch of [
          type('string'),
          type('string').pipe((data, ctx) => {
            const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
            return Number.isSafeInteger(value) ? value : ctx.error('an integer')
          }),
        ]) {
          const out = branch(data)
          if (!(out instanceof type.errors)) return out
        }
        return ctx.error('one of the members')
      }),
      control_id: type('string').pipe((data, ctx) => {
        const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
        return Number.isSafeInteger(value) ? value : ctx.error('an integer')
      }),
      status: type("'pass' | 'fail' | 'not_applicable'").describe('Status of the control.'),
    }),
  )
  .handler(async ({ input }) => { throw new Error('Not implemented') })

