export const getApiV4ProjectsIdSearchSemantic = os
  .route({
    method: 'GET',
    path: '/api/v4/projects/{id}/(-/)search/semantic',
    tags: ['Search'],
    summary: 'Search project code using natural language',
    description:
      'Introduced in GitLab 18.11.\n\nSearches indexed project code using semantic (meaning-based) similarity rather than\nkeyword matching. Use this when you do not know the exact symbol or file name, or\nto discover how a behavior is implemented across the codebase.\n\nPrimary use cases:\n- When you do not know the exact symbol or file path\n- To see how a behavior or feature is implemented across the codebase\n- To discover related implementations (clients, jobs, workers)\n\nHow to use:\n- Provide a concise, specific query with concrete keywords\n- Use directory_path to narrow scope (e.g. "app/services/")\n- Prefer precise intent over broad terms\n\nResults are grouped by file. Each file includes merged line ranges with content\nand a relevance score (0.0-1.0). The response includes an overall confidence\nlevel (high/medium/low/unknown) based on score distribution. Results are\nfiltered by Duo context exclusion settings.\n\nRequires semantic code search to be enabled and indexed for the project namespace.\n',
  })
  .input(
    type({
      id: type('unknown').pipe((data, ctx) => {
        for (const branch of [
          type('string'),
          type('string').pipe((data, ctx) => {
            const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
            return Number.isSafeInteger(value) ? value : ctx.error('an integer')
          }),
        ]) {
          const out = branch(data)
          if (!(out instanceof type.errors)) return out
        }
        return ctx.error('one of the members')
      }),
      q: type('string')
        .narrow((data, ctx) => [...data].length >= 1 || ctx.mustBe('at least 1 character'))
        .narrow((data, ctx) => [...data].length <= 1000 || ctx.mustBe('at most 1000 characters')),
      'directory_path?': type(
        type('string').narrow(
          (data, ctx) => [...data].length <= 100 || ctx.mustBe('at most 100 characters'),
        ),
      ).or('null'),
      'knn?': type('unknown').pipe(
        (data) => (data === 'null' ? null : data),
        type(
          type('string')
            .pipe((data, ctx) => {
              const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
              return Number.isSafeInteger(value) ? value : ctx.error('an integer')
            })
            .to('number.integer >= 1 & number.integer <= 100'),
        ).or('null'),
      ),
      'limit?': type('unknown').pipe(
        (data) => (data === 'null' ? null : data),
        type(
          type('string')
            .pipe((data, ctx) => {
              const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
              return Number.isSafeInteger(value) ? value : ctx.error('an integer')
            })
            .to('number.integer >= 1 & number.integer <= 100'),
        ).or('null'),
      ),
    }),
  )
  .output(APIEntitiesAiSemanticCodeResponseSchema)
  .handler(async ({ input }) => { throw new Error('Not implemented') })

