export const putApiV4GeoSitesId = os
  .route({
    method: 'PUT',
    path: '/api/v4/geo_sites/{id}',
    tags: ['Geo'],
    summary: 'Update a Geo site',
    description: 'Updates a specified Geo site.',
  })
  .input(
    type({
      id: type('string').pipe((data, ctx) => {
        const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
        return Number.isSafeInteger(value) ? value : ctx.error('an integer')
      }),
      'enabled?': type('boolean | null').describe('If `true`, the Geo site is enabled.'),
      'name?': type('string | null').describe(
        'Unique identifier for the Geo site. Must match `geo_node_name` if it is set in `gitlab.rb`, otherwise it must match `external_url`.',
      ),
      'url?': type('string | null').describe('User-facing URL of the Geo site.'),
      'internal_url?': type('string | null').describe(
        'URL defined on the primary site that secondary sites use to contact it. Returns `url` if not set.',
      ),
      'files_max_capacity?': type('number.integer >= 0 | null').describe(
        'Maximum concurrency of LFS and attachment backfill for the secondary site.',
      ),
      'repos_max_capacity?': type('number.integer >= 0 | null').describe(
        'Maximum concurrency of repository backfill for the secondary site.',
      ),
      'verification_max_capacity?': type('number.integer >= 0 | null').describe(
        'Maximum concurrency of verification for the site.',
      ),
      'container_repositories_max_capacity?': type('number.integer >= 0 | null').describe(
        'Maximum concurrency of container repository sync for the site.',
      ),
      'sync_object_storage?': type('boolean | null').describe(
        'If `true`, the secondary Geo site replicates blobs in object storage.',
      ),
      'selective_sync_type?': type('string | null').describe(
        'Limit syncing to only specific groups, or shards. Valid values: `"namespaces"`, `"shards"`, or `null`',
      ),
      'selective_sync_shards?': type('string[] | null').describe(
        'Repository storages to sync projects from if `selective_sync_type` is `shards`.',
      ),
      'selective_sync_namespace_ids?': type('number.integer[] | null').describe(
        'IDs of groups to sync if `selective_sync_type` is `namespaces`.',
      ),
      'selective_sync_organization_ids?': type('number.integer[] | null').describe(
        'IDs of organizations to sync if `selective_sync_type` is `organizations`.',
      ),
      'minimum_reverification_interval?': type('number.integer | null').describe(
        'Interval, in days, after which verification expires and is repeated. Has no effect when set on a secondary site.',
      ),
      'checksum_mismatch_report_threshold?': type('number.integer | null').describe(
        'Number of consecutive checksum mismatches on a secondary site before it reports the resource to the primary for self-heal re-verification. Read from the secondary site, and has no effect when set on the primary.',
      ),
      'checksum_mismatch_self_heal_cooldown_minutes?': type('number.integer | null').describe(
        'Minimum time, in minutes, between self-heal re-verification triggers for the same resource. The primary and each secondary site use their own value. Secondary sites use it to throttle re-reporting the same resource, and the primary uses it to throttle re-verifying an already-verified resource.',
      ),
      'blob_download_timeout?': type(
        'number.integer >= 1 & number.integer <= 86400 | null',
      ).describe(
        'Maximum time (in seconds) for blob downloads during Geo sync. [Introduced](https://gitlab.com/gitlab-org/gitlab/-/work_items/569919) in GitLab 18.10.',
      ),
    }),
  )
  .output(APIEntitiesGeoSiteSchema)
  .handler(async ({ input }) => { throw new Error('Not implemented') })

