export const getApiV4ProjectsIdDependencyProxyPackagesNpmPackageNameFileName = os
  .route({
    method: 'GET',
    path: '/api/v4/projects/{id}/dependency_proxy/packages/npm/{package_name}/-/{file_name}',
    tags: ['Dependency proxy'],
    summary: 'Proxy the download of a NPM package tarball',
    description: 'This feature was introduced in 16.11',
  })
  .input(
    type({
      id: type('unknown').pipe((data, ctx) => {
        for (const branch of [
          type('string'),
          type('string').pipe((data, ctx) => {
            const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
            return Number.isSafeInteger(value) ? value : ctx.error('an integer')
          }),
        ]) {
          const out = branch(data)
          if (!(out instanceof type.errors)) return out
        }
        return ctx.error('one of the members')
      }),
      package_name: type('string').and(
        /^(?:@((?:(?:[a-zA-Z0-9_.][a-zA-Z0-9_\-.]{0,254}[a-zA-Z0-9_\-]|[a-zA-Z0-9_])(?:(?<!\.git|\.atom))))\/)?[\-+._a-zA-Z0-9]+$/,
      ),
      file_name: type('string'),
    }),
  )
  .handler(async ({ input }) => { throw new Error('Not implemented') })

