export const getApiV4AdminDataManagementModelName = os
  .route({
    method: 'GET',
    path: '/api/v4/admin/data_management/{model_name}',
    tags: ['Data management'],
    summary: 'Retrieve model information',
    description:
      'Retrieves information about a data model in an instance. Only available to administrators. Supports keyset pagination on the primary key of the model. To use keyset pagination, set `pagination=keyset`. By default, keyset pagination returns 20 records per page in ascending order. Use `sort` to set the order and `per_page` to set the number of records per page.',
  })
  .input(
    type({
      model_name: type('string').narrow(
        (data, ctx) => [...data].length >= 1 || ctx.mustBe('at least 1 character'),
      ),
      'page?': type('unknown').pipe(
        (data) => (data === 'null' ? null : data),
        type(
          type('string').pipe((data, ctx) => {
            const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
            return Number.isSafeInteger(value) ? value : ctx.error('an integer')
          }),
        ).or('null'),
      ),
      'per_page?': type('unknown').pipe(
        (data) => (data === 'null' ? null : data),
        type(
          type('string').pipe((data, ctx) => {
            const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
            return Number.isSafeInteger(value) ? value : ctx.error('an integer')
          }),
        ).or('null'),
      ),
      'identifiers?': type('unknown').pipe(
        (data) => (data === 'null' ? null : data),
        type(
          type('unknown').pipe((data, ctx) => {
            for (const branch of [
              type('unknown').pipe(
                (data) => (data === 'null' ? null : data),
                type(
                  type('unknown').pipe(
                    (data) => (data === undefined || Array.isArray(data) ? data : [data]),
                    type(
                      type('string').pipe((data, ctx) => {
                        const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
                        return Number.isSafeInteger(value) ? value : ctx.error('an integer')
                      }),
                    ).array(),
                  ),
                ).or('null'),
              ),
              type('unknown').pipe(
                (data) => (data === 'null' ? null : data),
                type(
                  type('unknown')
                    .pipe((data) => (data === undefined || Array.isArray(data) ? data : [data]))
                    .to('string[]'),
                ).or('null'),
              ),
            ]) {
              const out = branch(data)
              if (!(out instanceof type.errors)) return out
            }
            return ctx.error('one of the members')
          }),
        ).or('null'),
      ),
      'checksum_state?': type("'pending' | 'started' | 'succeeded' | 'failed' | 'disabled' | null"),
      'cursor?': type('string | null'),
      'sort?': type("'asc' | 'desc' | null"),
    }),
  )
  .output(type(APIEntitiesAdminModelSchema).array())
  .handler(async ({ input }) => { throw new Error('Not implemented') })

