export const postApiV4UsersUserIdImpersonationTokens = os
  .route({
    method: 'POST',
    path: '/api/v4/users/{user_id}/impersonation_tokens',
    tags: ['Access tokens'],
    summary: 'Create an impersonation token',
    description:
      'Creates an impersonation token for a specified user. These tokens are used to act on behalf of a user and can perform API calls as well as Git read and write actions. These tokens are not visible to the associated user on their profile settings page. To create a fine-grained impersonation token, use `granular_scopes` instead of `scopes`. The scopes in `granular_scopes` apply to the user the token is for. With `selected_memberships`, that user must have access to each group and project listed. Either `scopes` or `granular_scopes` is required. Token values are included with the response, but cannot be retrieved later. Administrators only. The `last_used_ips` attribute was [introduced](https://gitlab.com/gitlab-org/gitlab/-/merge_requests/242819) in GitLab 19.2 and made generally available in GitLab 19.4. The `granular_scopes` parameter was [introduced](https://gitlab.com/gitlab-org/gitlab/-/merge_requests/243990) in GitLab 19.2, and the `granular_scopes` attribute in the response was [introduced](https://gitlab.com/gitlab-org/gitlab/-/issues/632315) in GitLab 19.5.',
    successStatus: 201,
  })
  .input(
    type({
      user_id: type('string').pipe((data, ctx) => {
        const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
        return Number.isSafeInteger(value) ? value : ctx.error('an integer')
      }),
      name: type('string | null').describe('Name of the impersonation token.'),
      'description?': type('string | null').describe(
        'Description of the impersonation token. Limited to 255 characters.',
      ),
      'expires_at?': type(
        type(
          /^(?:(?:\d\d[2468][048]|\d\d[13579][26]|\d\d0[48]|[02468][048]00|[13579][26]00)-02-29|\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\d|30)|(?:02)-(?:0[1-9]|1\d|2[0-8])))$/,
        ),
      )
        .or('null')
        .describe(
          'Date when the impersonation token expires. If omitted, the token does not expire, which is accepted only when [token expiry is not enforced](https://docs.gitlab.com/user/profile/personal_access_tokens/#access-token-expiration).',
        ),
      'scopes?': type('string[] | null').describe(
        'Array of approved scopes. For a list of possible values, see [access token scopes](https://docs.gitlab.com/security/tokens/access_token_scopes/). Required if `granular_scopes` is not provided. Mutually exclusive with `granular_scopes`.',
      ),
      'granular_scopes?': type(
        type(
          type({
            access: type(
              "'personal_projects' | 'all_memberships' | 'selected_memberships' | 'user' | 'instance'",
            ).describe('Access to configure for the granular scope.'),
            permissions: type('string[] | null').describe(
              'List of permissions for the granular scope.',
            ),
            'project_ids?': type('number.integer[] | null').describe(
              'IDs of projects to associate with the granular scope, when access is `selected_memberships`.',
            ),
            'group_ids?': type('number.integer[] | null').describe(
              'IDs of groups to associate with the granular scope, when access is `selected_memberships`.',
            ),
          }),
        ).array(),
      )
        .or('null')
        .describe(
          'List of granular scopes to assign, one object for each scope. Each scope pairs an access level with a list of permissions. Mutually exclusive with `scopes`.',
        ),
    }),
  )
  .output(APIEntitiesImpersonationTokenWithTokenSchema)
  .handler(async ({ input }) => { throw new Error('Not implemented') })

