export const getApiV4GroupsIdLabelsName = os
  .route({
    method: 'GET',
    path: '/api/v4/groups/{id}/labels/{name}',
    tags: ['Labels'],
    summary: 'Retrieve a group label',
    description: 'Retrieves a specified group label.',
  })
  .input(
    type({
      id: type('string'),
      name: type('unknown').pipe((data, ctx) => {
        for (const branch of [
          type('string'),
          type('string').pipe((data, ctx) => {
            const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
            return Number.isSafeInteger(value) ? value : ctx.error('an integer')
          }),
        ]) {
          const out = branch(data)
          if (!(out instanceof type.errors)) return out
        }
        return ctx.error('one of the members')
      }),
      'include_ancestor_groups?': type('unknown').pipe(
        (data) => (data === 'null' ? null : data),
        type(
          type(/^(?:true|1|yes|on|y|enabled|false|0|no|off|n|disabled)$/i).pipe((data) =>
            /^(?:true|1|yes|on|y|enabled)$/i.test(data),
          ),
        ).or('null'),
      ),
      'include_descendant_groups?': type('unknown').pipe(
        (data) => (data === 'null' ? null : data),
        type(
          type(/^(?:true|1|yes|on|y|enabled|false|0|no|off|n|disabled)$/i).pipe((data) =>
            /^(?:true|1|yes|on|y|enabled)$/i.test(data),
          ),
        ).or('null'),
      ),
      'only_group_labels?': type('unknown').pipe(
        (data) => (data === 'null' ? null : data),
        type(
          type(/^(?:true|1|yes|on|y|enabled|false|0|no|off|n|disabled)$/i).pipe((data) =>
            /^(?:true|1|yes|on|y|enabled)$/i.test(data),
          ),
        ).or('null'),
      ),
    }),
  )
  .output(APIEntitiesGroupLabelSchema)
  .handler(async ({ input }) => { throw new Error('Not implemented') })

