export const putApiV4SnippetsId = os
  .route({
    method: 'PUT',
    path: '/api/v4/snippets/{id}',
    tags: ['Snippets'],
    summary: 'Update snippet',
    description:
      'Updates a specified snippet. The user must have permission to change the snippet.',
  })
  .input(
    type({
      id: type('string').pipe((data, ctx) => {
        const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
        return Number.isSafeInteger(value) ? value : ctx.error('an integer')
      }),
      'content?': type('string')
        .narrow((data, ctx) => [...data].length >= 1 || ctx.mustBe('at least 1 character'))
        .describe(
          'The content of a snippet. Deprecated. Use `files` instead. Mutually exclusive with `files`. At least one of `content`, `description`, `files`, `file_name`, `title`, `visibility` must be provided.',
        ),
      'description?': type('string | null').describe(
        'Description of the snippet. At least one of `content`, `description`, `files`, `file_name`, `title`, `visibility` must be provided.',
      ),
      'file_name?': type('string | null').describe(
        'The name of a snippet file. Deprecated. Use `files` instead. Mutually exclusive with `files`. At least one of `content`, `description`, `files`, `file_name`, `title`, `visibility` must be provided.',
      ),
      'title?': type('string')
        .narrow((data, ctx) => [...data].length >= 1 || ctx.mustBe('at least 1 character'))
        .describe(
          'Title of the snippet. At least one of `content`, `description`, `files`, `file_name`, `title`, `visibility` must be provided.',
        ),
      'visibility?': type("'private' | 'internal' | 'public' | null").describe(
        'Visibility level for the snippet. On GitLab.com, the `internal` value is not available. At least one of `content`, `description`, `files`, `file_name`, `title`, `visibility` must be provided.',
      ),
      'files?': type(
        type(
          type({
            action: type("'create' | 'update' | 'delete' | 'move'").describe(
              'The type of action to perform on the file, must be one of: create, update, delete, move',
            ),
            'content?': type('string')
              .narrow((data, ctx) => [...data].length >= 1 || ctx.mustBe('at least 1 character'))
              .describe('Content of the snippet file.'),
            'file_path?': type('string | null').describe('Path of the snippet file.'),
            'previous_path?': type('string | null').describe('Previous path of the snippet file.'),
          }),
        ).array(),
      )
        .or('null')
        .describe(
          'Array of files to update for the snippet. Required when the snippet has multiple files. Mutually exclusive with `content`, `file_name`. At least one of `content`, `description`, `files`, `file_name`, `title`, `visibility` must be provided.',
        ),
    }),
  )
  .output(APIEntitiesPersonalSnippetSchema)
  .handler(async ({ input }) => { throw new Error('Not implemented') })

