export const postApiV4GroupsIdAccessTokens = os
  .route({
    method: 'POST',
    path: '/api/v4/groups/{id}/access_tokens',
    tags: ['Access tokens'],
    summary: 'Create a group access token',
    description:
      'Creates a group access token for a specified group. You cannot create a token with an access level greater than your account. For example, a user with the Maintainer role cannot create a group access token with the Owner role. You must use a personal access token with this endpoint. You cannot authenticate with a group access token. You must have the Owner role for the group.',
    successStatus: 201,
  })
  .input(
    type({
      id: type('string'),
      name: type('string | null').describe('Name of the access token.'),
      'description?': type('string | null').describe(
        'Description of the access token. Limited to 255 characters.',
      ),
      'expires_at?': type(
        type(
          /^(?:(?:\d\d[2468][048]|\d\d[13579][26]|\d\d0[48]|[02468][048]00|[13579][26]00)-02-29|\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\d|30)|(?:02)-(?:0[1-9]|1\d|2[0-8])))$/,
        ),
      )
        .or('null')
        .describe(
          'Date when the access token expires. If omitted, the token does not expire, which is accepted only when [token expiry is not enforced](https://docs.gitlab.com/user/profile/personal_access_tokens/#access-token-expiration).',
        ),
      scopes: type(
        type.enumerated(
          'api',
          'read_api',
          'create_runner',
          'manage_runner',
          'k8s_proxy',
          'self_rotate',
          'mcp',
          'mcp_orbit',
          'granular',
          'read_repository',
          'write_repository',
          'read_registry',
          'write_registry',
          'read_virtual_registry',
          'write_virtual_registry',
          'read_observability',
          'write_observability',
          'ai_features',
        ),
      )
        .array()
        .describe(
          'List of [scopes](https://docs.gitlab.com/security/tokens/access_token_scopes/) available to the token.',
        ),
      'access_level?': type('10 | 15 | 20 | 25 | 30 | 40 | 50 | null').describe(
        'The access level of the token in the group',
      ),
    }),
  )
  .output(APIEntitiesResourceAccessTokenWithTokenSchema)
  .handler(async ({ input }) => { throw new Error('Not implemented') })

