export const getApiV4ProjectsIdRepositoryChangelog = os
  .route({
    method: 'GET',
    path: '/api/v4/projects/{id}/repository/changelog',
    tags: ['Repositories'],
    summary: 'Generate changelog data',
    description:
      'Generates changelog data based on commits in a repository, without committing them to a changelog file. Works exactly like `POST /projects/:id/repository/changelog`, except the changelog data is not committed to any changelog file. Add a `.txt` suffix to the path, as in `GET /projects/:id/repository/changelog.txt`, to return the changelog as plain text Markdown instead of JSON.',
  })
  .input(
    type({
      id: type('unknown').pipe((data, ctx) => {
        for (const branch of [
          type('string'),
          type('string').pipe((data, ctx) => {
            const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
            return Number.isSafeInteger(value) ? value : ctx.error('an integer')
          }),
        ]) {
          const out = branch(data)
          if (!(out instanceof type.errors)) return out
        }
        return ctx.error('one of the members')
      }),
      version: type('string')
        .and(
          /(?:(?:(0|[1-9]\d*))\.(?:(0|[1-9]\d*))\.(?:(0|[1-9]\d*)))(?:(?:-((?:\d*[a-zA-Z\-][0-9a-zA-Z\-]*|[1-9]\d*|0)(?:\.(?:\d*[a-zA-Z\-][0-9a-zA-Z\-]*|[1-9]\d*|0))*))?(?:\+([0-9a-zA-Z\-]+(?:\.[0-9a-zA-Z\-]+)*))?)/,
        )
        .narrow((data, ctx) => [...data].length >= 1 || ctx.mustBe('at least 1 character')),
      'from?': type('string | null'),
      'to?': type('string | null'),
      'date?': type(
        type(
          /^(?:(?:\d\d[2468][048]|\d\d[13579][26]|\d\d0[48]|[02468][048]00|[13579][26]00)-02-29|\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\d|30)|(?:02)-(?:0[1-9]|1\d|2[0-8])))T(?:(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z|([+-](?:[01]\d|2[0-3]):[0-5]\d)))$/,
        ),
      ).or('null'),
      'trailer?': type('string | null'),
      'config_file?': type('string | null'),
      'config_file_ref?': type('string | null'),
    }),
  )
  .output(APIEntitiesChangelogSchema)
  .handler(async ({ input }) => { throw new Error('Not implemented') })

export const postApiV4ProjectsIdRepositoryChangelog = os
  .route({
    method: 'POST',
    path: '/api/v4/projects/{id}/repository/changelog',
    tags: ['Repositories'],
    summary: 'Add changelog data to file',
    description:
      'Generates changelog data based on commits in a repository and commits it to a changelog file. Given a semantic version and a range of commits, GitLab generates a changelog for all commits that use a specific Git trailer, and adds a new Markdown section to the changelog file. The output format can be customized. Parsing the changelog configuration is limited to 2 seconds. If the request times out, reduce the size of the changelog configuration file.',
  })
  .input(
    type({
      id: type('unknown').pipe((data, ctx) => {
        for (const branch of [
          type('string'),
          type('string').pipe((data, ctx) => {
            const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
            return Number.isSafeInteger(value) ? value : ctx.error('an integer')
          }),
        ]) {
          const out = branch(data)
          if (!(out instanceof type.errors)) return out
        }
        return ctx.error('one of the members')
      }),
      'from?': type('string | null').describe(
        'First commit in the range of commits, as a SHA, to use for the changelog. This commit is not included in the changelog. If omitted, the most recent stable version tag before `version` is used. Tags in `X.Y.Z` or `vX.Y.Z` format are recognized, and pre-release tags such as `v1.0.0-pre1` are ignored. If no such tag exists, an error is returned and you must set `from`.',
      ),
      'to?': type('string | null').describe(
        'Last commit in the range of commits, as a SHA or a branch or tag name, to use for the changelog. This commit is included in the changelog. If omitted, uses the latest commit on the default branch. For the Add changelog data to file operation, uses the latest commit on `branch` instead. The range can contain at most 15,000 commits.',
      ),
      'date?': type(
        type(
          /^(?:(?:\d\d[2468][048]|\d\d[13579][26]|\d\d0[48]|[02468][048]00|[13579][26]00)-02-29|\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\d|30)|(?:02)-(?:0[1-9]|1\d|2[0-8])))T(?:(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z|([+-](?:[01]\d|2[0-3]):[0-5]\d)))$/,
        ),
      )
        .or('null')
        .describe('Date and time of the release. Defaults to the current time.'),
      'trailer?': type('string | null').describe(
        'Git trailer to use for including commits. Case-sensitive: `Example` does not match `example` or `eXaMpLE`.',
      ),
      'config_file?': type('string | null').describe(
        "Path to the changelog configuration file in the project's Git repository. If omitted, uses `.gitlab/changelog_config.yml`.",
      ),
      'config_file_ref?': type('string | null').describe(
        'Git reference, for example a branch, where the changelog configuration file is defined. Defaults to the default branch of the repository. [Introduced](https://gitlab.com/gitlab-org/gitlab/-/issues/426108) in GitLab 18.2.',
      ),
      'branch?': type('string | null').describe(
        "Name of the branch to commit the changelog changes to. If omitted, defaults to the project's default branch.",
      ),
      'file?': type('string | null').describe('File to commit the changes to.'),
      'message?': type('string | null').describe(
        'Commit message to use when committing the changelog changes. If omitted, defaults to `Add changelog for version X`, where `X` is the value of the `version` parameter.',
      ),
    }),
  )
  .handler(async ({ input }) => { throw new Error('Not implemented') })

