export const postApiV4ProjectsIdPackagesProtectionRules = os
  .route({
    method: 'POST',
    path: '/api/v4/projects/{id}/packages/protection/rules',
    tags: ['Projects'],
    summary: 'Create a package protection rule',
    description: 'Creates a package protection rule for a specified project.',
    successStatus: 201,
  })
  .input(
    type({
      id: type('unknown').pipe((data, ctx) => {
        for (const branch of [
          type('string'),
          type('string').pipe((data, ctx) => {
            const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
            return Number.isSafeInteger(value) ? value : ctx.error('an integer')
          }),
        ]) {
          const out = branch(data)
          if (!(out instanceof type.errors)) return out
        }
        return ctx.error('one of the members')
      }),
      package_name_pattern: type('string | null').describe(
        'Package name protected by the protection rule, for example `@my-scope/my-package-*`. Wildcard character `*` is allowed.',
      ),
      package_type: type(
        "'cargo' | 'conan' | 'generic' | 'helm' | 'maven' | 'npm' | 'nuget' | 'pypi' | 'rubygems' | 'terraform_module'",
      ).describe('Package type protected by the protection rule, for example `npm`.'),
      'minimum_access_level_for_delete?': type("'owner' | 'admin' | null").describe(
        'Minimum GitLab access level required to delete a package. If the value is `null`, the default minimum access level is `maintainer`. Must be provided when `minimum_access_level_for_push` is not set. Behind a feature flag named `packages_protected_packages_delete`. Disabled by default. At least one of `minimum_access_level_for_push`, `minimum_access_level_for_delete` must be provided.',
      ),
      'minimum_access_level_for_push?': type("'maintainer' | 'owner' | 'admin' | null").describe(
        'Minimum GitLab access level required to push a package. If the value is `null`, the default minimum access level is `developer`. Must be provided when `minimum_access_level_for_delete` is not set. At least one of `minimum_access_level_for_push`, `minimum_access_level_for_delete` must be provided.',
      ),
    }),
  )
  .output(APIEntitiesProjectsPackagesProtectionRuleSchema)
  .handler(async ({ input }) => { throw new Error('Not implemented') })

