export const postApiV4ProjectsIdMergeRequestsMergeRequestIidApprove = os
  .route({
    method: 'POST',
    path: '/api/v4/projects/{id}/merge_requests/{merge_request_iid}/approve',
    tags: ['Merge request approvals'],
    summary: 'Approve merge request',
    description:
      'Approves a specified merge request. The currently authenticated user must be an eligible approver. The `sha` parameter ensures you are approving the current version of the merge request. If defined, the value must match the merge request’s HEAD commit SHA, and the diff must not have changed since a version with that SHA, for example after a target branch change. Otherwise returns a `409 Conflict` response. An approval sent immediately after the merge request is created can come before its commit is processed, and a new commit can then reset the approval. To avoid this, wait until `detailed_merge_status` is not `checking` or `approvals_syncing` and the merge request diff has a `patch_id_sha`, or send `sha`. With `sha`, GitLab records the approved version even before a diff exists, so a later push does not reset the approval. The response has the same attributes as retrieving the approval state, which depend on the edition.',
    successStatus: 201,
  })
  .input(
    type({
      id: type('unknown').pipe((data, ctx) => {
        for (const branch of [
          type('string'),
          type('string').pipe((data, ctx) => {
            const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
            return Number.isSafeInteger(value) ? value : ctx.error('an integer')
          }),
        ]) {
          const out = branch(data)
          if (!(out instanceof type.errors)) return out
        }
        return ctx.error('one of the members')
      }),
      merge_request_iid: type('string').pipe((data, ctx) => {
        const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
        return Number.isSafeInteger(value) ? value : ctx.error('an integer')
      }),
      'sha?': type('string | null').describe(
        'SHA at `HEAD` of the source branch of the merge request.',
      ),
      'publish_review?': type('boolean | null').describe(
        'If `true`, submits pending review comments.',
      ),
      'approval_password?': type('string | null').describe(
        "Current user's password, needed if [user re-authentication to approve](https://docs.gitlab.com/user/project/merge_requests/approvals/settings/#require-user-re-authentication-to-approve) is enabled in the project settings. Always fails if the group or GitLab Self-Managed instance is configured to force SAML authentication.",
      ),
    }),
  )
  .output(APIEntitiesMergeRequestApprovalsSchema)
  .handler(async ({ input }) => { throw new Error('Not implemented') })

