export const getApiV4ProjectsIdCiLint = os
  .route({
    method: 'GET',
    path: '/api/v4/projects/{id}/ci/lint',
    tags: ['CI lint'],
    summary: 'Validate existing CI/CD configuration',
    description:
      'Validates the existing `.gitlab-ci.yml` configuration for a specified project. The validation runs in the context of the project, using the CI/CD variables of the project and searching the files of the project for `include:local` entries. If the `ci_lint_api_require_authentication` setting is enabled, this endpoint requires authentication, including for public projects. This endpoint does not accept CI/CD job tokens. Use a personal, project, or group access token instead.',
  })
  .input(
    type({
      id: type('unknown').pipe((data, ctx) => {
        for (const branch of [
          type('string'),
          type('string').pipe((data, ctx) => {
            const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
            return Number.isSafeInteger(value) ? value : ctx.error('an integer')
          }),
        ]) {
          const out = branch(data)
          if (!(out instanceof type.errors)) return out
        }
        return ctx.error('one of the members')
      }),
      'sha?': type('string | null'),
      'content_ref?': type('string | null'),
      'dry_run?': type('unknown').pipe(
        (data) => (data === 'null' ? null : data),
        type(
          type(/^(?:true|1|yes|on|y|enabled|false|0|no|off|n|disabled)$/i).pipe((data) =>
            /^(?:true|1|yes|on|y|enabled)$/i.test(data),
          ),
        ).or('null'),
      ),
      'include_jobs?': type('unknown').pipe(
        (data) => (data === 'null' ? null : data),
        type(
          type(/^(?:true|1|yes|on|y|enabled|false|0|no|off|n|disabled)$/i).pipe((data) =>
            /^(?:true|1|yes|on|y|enabled)$/i.test(data),
          ),
        ).or('null'),
      ),
      'ref?': type('string | null'),
      'dry_run_ref?': type('string | null'),
    }),
  )
  .output(APIEntitiesCiLintResultSchema)
  .handler(async ({ input }) => { throw new Error('Not implemented') })

