export const postApiV4GroupsIdInvitations = os
  .route({
    method: 'POST',
    path: '/api/v4/groups/{id}/invitations',
    tags: ['Invitations'],
    summary: 'Add a member to a group',
    description:
      'Adds a member to a group. You can specify a user ID or invite a user by email. You must have the Owner role for the group. On GitLab Self-Managed, an administrator must add the user if new user accounts or user invitations are not allowed, and must approve the invitation if administrator approval for role promotions is enabled. If an invitation fails, the response has a `status` of `error` and a `message` object that maps each email address or username to its error. To enable Manage non-billable promotions, enable the `enable_member_promotion_management` application setting. Users whose requests are queued for administrator approval are listed in `queued_users`.',
    successStatus: 201,
  })
  .input(
    type({
      id: type('string'),
      access_level: type('10 | 15 | 20 | 25 | 30 | 40 | 50 | 5').describe(
        'Access level to grant to the invited user. For a list of values, see [roles](https://docs.gitlab.com/user/permissions/#default-roles). On Premium and Ultimate, `5` (Minimal access) is also valid when `id` is a top-level group.',
      ),
      'email?': type('string[] | null').describe(
        'Email address of the member to invite, or multiple email addresses separated by commas. Required if `user_id` is not provided.',
      ),
      'user_id?': type('string[] | null').describe(
        'ID of the user to invite, or multiple IDs separated by commas. Required if `email` is not provided.',
      ),
      'expires_at?': type(
        type(
          /^(?:(?:\d\d[2468][048]|\d\d[13579][26]|\d\d0[48]|[02468][048]00|[13579][26]00)-02-29|\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\d|30)|(?:02)-(?:0[1-9]|1\d|2[0-8])))T(?:(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z|([+-](?:[01]\d|2[0-3]):[0-5]\d)))$/,
        ),
      )
        .or('null')
        .describe('Date when the invitation expires.'),
      'invite_source?': type('string | null').describe(
        'Source of the invitation that starts the member creation process.',
      ),
      'member_role_id?': type('number.integer | null').describe(
        'ID of a member role to assign to the invited user. Ultimate only.',
      ),
    }),
  )
  .output(APIEntitiesInvitationSchema)
  .handler(async ({ input }) => { throw new Error('Not implemented') })

