export const getApiV4GroupsIdPackages = os
  .route({
    method: 'GET',
    path: '/api/v4/groups/{id}/packages',
    tags: ['Packages'],
    summary: 'List all packages for a group',
    description:
      'Lists all packages for a specified group. When accessed without authentication, only packages of public projects are returned. By default, packages with `default`, `deprecated`, and `error` status are returned. Use the `status` parameter to view other packages. Packages of non-public projects are returned only for projects where you have at least the Reporter role. Packages with `processing` status can contain malformed data or be broken. In the response, `creator_id` is the ID of the user who created the package, and is `null` when a deploy token created the package. For a Conan package, `name` contains the recipe, and `conan_package_name` contains the package name. Other package types do not have this field. In `_links`, `web_path` is the path to the package details page in GitLab, returned only if the package has status `default` or `deprecated`, and `delete_api_path` is the API path to delete the package, returned only if you have permission to delete it.',
  })
  .input(
    type({
      id: type('unknown').pipe((data, ctx) => {
        for (const branch of [
          type('string'),
          type('string').pipe((data, ctx) => {
            const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
            return Number.isSafeInteger(value) ? value : ctx.error('an integer')
          }),
        ]) {
          const out = branch(data)
          if (!(out instanceof type.errors)) return out
        }
        return ctx.error('one of the members')
      }),
      'exclude_subgroups?': type('unknown').pipe(
        (data) => (data === 'null' ? null : data),
        type(
          type(/^(?:true|1|yes|on|y|enabled|false|0|no|off|n|disabled)$/i).pipe((data) =>
            /^(?:true|1|yes|on|y|enabled)$/i.test(data),
          ),
        ).or('null'),
      ),
      'page?': type('unknown').pipe(
        (data) => (data === 'null' ? null : data),
        type(
          type('string').pipe((data, ctx) => {
            const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
            return Number.isSafeInteger(value) ? value : ctx.error('an integer')
          }),
        ).or('null'),
      ),
      'per_page?': type('unknown').pipe(
        (data) => (data === 'null' ? null : data),
        type(
          type('string').pipe((data, ctx) => {
            const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
            return Number.isSafeInteger(value) ? value : ctx.error('an integer')
          }),
        ).or('null'),
      ),
      'order_by?': type("'created_at' | 'name' | 'version' | 'type' | 'project_path' | null"),
      'sort?': type("'asc' | 'desc' | null"),
      'package_type?': type(
        "'maven' | 'npm' | 'conan' | 'nuget' | 'pypi' | 'composer' | 'generic' | 'golang' | 'debian' | 'rubygems' | 'helm' | 'terraform_module' | 'rpm' | 'ml_model' | 'cargo' | 'swift'",
      ).or('null'),
      'package_name?': type('string | null'),
      'package_version?': type('string | null'),
      'include_versionless?': type('unknown').pipe(
        (data) => (data === 'null' ? null : data),
        type(
          type(/^(?:true|1|yes|on|y|enabled|false|0|no|off|n|disabled)$/i).pipe((data) =>
            /^(?:true|1|yes|on|y|enabled)$/i.test(data),
          ),
        ).or('null'),
      ),
      'status?': type(
        "'default' | 'hidden' | 'processing' | 'error' | 'pending_destruction' | 'deprecated' | null",
      ),
    }),
  )
  .output(type(APIEntitiesPackageSchema).array())
  .handler(async ({ input }) => { throw new Error('Not implemented') })

