export const getApiV4GroupsIdDebianDistributions = os
  .route({
    method: 'GET',
    path: '/api/v4/groups/{id}/-/debian_distributions',
    tags: ['Packages: Debian'],
    summary: 'List all Debian group distributions',
    description:
      'Lists all Debian distributions for a specified group. `suite` filters the results by suite.',
  })
  .input(
    type({
      id: type('unknown').pipe((data, ctx) => {
        for (const branch of [
          type('string'),
          type('string').pipe((data, ctx) => {
            const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
            return Number.isSafeInteger(value) ? value : ctx.error('an integer')
          }),
        ]) {
          const out = branch(data)
          if (!(out instanceof type.errors)) return out
        }
        return ctx.error('one of the members')
      }),
      'page?': type('unknown').pipe(
        (data) => (data === 'null' ? null : data),
        type(
          type('string').pipe((data, ctx) => {
            const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
            return Number.isSafeInteger(value) ? value : ctx.error('an integer')
          }),
        ).or('null'),
      ),
      'per_page?': type('unknown').pipe(
        (data) => (data === 'null' ? null : data),
        type(
          type('string').pipe((data, ctx) => {
            const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
            return Number.isSafeInteger(value) ? value : ctx.error('an integer')
          }),
        ).or('null'),
      ),
      'codename?': type(
        type('string').and(/(?:^(?:[0-9A-Za-z\u017F\u212A][\x2D.0-9A-Za-z\u017F\u212A]*)$)/),
      ).or('null'),
      'suite?': type(
        type('string').and(/(?:^(?:[0-9A-Za-z\u017F\u212A][\x2D.0-9A-Za-z\u017F\u212A]*)$)/),
      ).or('null'),
      'origin?': type(
        type('string').and(/(?:^(?:[0-9A-Za-z\u017F\u212A][\x2D.0-9A-Za-z\u017F\u212A]*)$)/),
      ).or('null'),
      'label?': type(
        type('string').and(/(?:^(?:[0-9A-Za-z\u017F\u212A][\x2D.0-9A-Za-z\u017F\u212A]*)$)/),
      ).or('null'),
      'version?': type(
        type('string').and(
          /(?:^(?:(?:([0-9]{1,9}):)?([0-9][+.0-9A-Za-z~\u017F\u212A]*)(-[+.0-9A-Za-z~\u017F\u212A]+){0,14}(?<!-))$)/,
        ),
      ).or('null'),
      'description?': type('string | null'),
      'valid_time_duration_seconds?': type('unknown').pipe(
        (data) => (data === 'null' ? null : data),
        type(
          type('string').pipe((data, ctx) => {
            const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
            return Number.isSafeInteger(value) ? value : ctx.error('an integer')
          }),
        ).or('null'),
      ),
      'components?': type('unknown').pipe(
        (data) => {
          if (typeof data !== 'string') return data
          const text = data
          return text === '' ? [] : text.split(',')
        },
        type('unknown').pipe(
          (data) => (data === 'null' ? null : data),
          type(
            type('unknown')
              .pipe((data) => (data === undefined || Array.isArray(data) ? data : [data]))
              .to('string[]'),
          ).or('null'),
        ),
      ),
      'architectures?': type('unknown').pipe(
        (data) => {
          if (typeof data !== 'string') return data
          const text = data
          return text === '' ? [] : text.split(',')
        },
        type('unknown').pipe(
          (data) => (data === 'null' ? null : data),
          type(
            type('unknown')
              .pipe((data) => (data === undefined || Array.isArray(data) ? data : [data]))
              .to('string[]'),
          ).or('null'),
        ),
      ),
    }),
  )
  .output(type(APIEntitiesPackagesDebianDistributionSchema).array())
  .handler(async ({ input }) => { throw new Error('Not implemented') })

