export const putApiV4BroadcastMessagesId = os
  .route({
    method: 'PUT',
    path: '/api/v4/broadcast_messages/{id}',
    tags: ['Broadcast messages'],
    summary: 'Update a broadcast message',
    description:
      'Updates a specified broadcast message. Broadcast messages are publicly accessible through the API regardless of targeting settings. Do not include sensitive or confidential information.',
  })
  .input(
    type({
      id: type('string').pipe((data, ctx) => {
        const value = /^-?(?:0|[1-9]\d*)$/.test(data) ? Number(data) : Number.NaN
        return Number.isSafeInteger(value) ? value : ctx.error('an integer')
      }),
      'message?': type('string | null').describe('Message to display.'),
      'starts_at?': type(
        type(
          /^(?:(?:\d\d[2468][048]|\d\d[13579][26]|\d\d0[48]|[02468][048]00|[13579][26]00)-02-29|\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\d|30)|(?:02)-(?:0[1-9]|1\d|2[0-8])))T(?:(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z|([+-](?:[01]\d|2[0-3]):[0-5]\d)))$/,
        ),
      )
        .or('null')
        .describe('Starting time, in UTC. When creating a message, defaults to the current time.'),
      'ends_at?': type(
        type(
          /^(?:(?:\d\d[2468][048]|\d\d[13579][26]|\d\d0[48]|[02468][048]00|[13579][26]00)-02-29|\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\d|30)|(?:02)-(?:0[1-9]|1\d|2[0-8])))T(?:(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z|([+-](?:[01]\d|2[0-3]):[0-5]\d)))$/,
        ),
      )
        .or('null')
        .describe(
          'Ending time, in UTC. When creating a message, defaults to one hour after the current time.',
        ),
      'color?': type('string | null').describe(
        'Background color hex code. Deprecated. Use `theme` instead.',
      ),
      'font?': type('string | null').describe(
        'Foreground color hex code. Deprecated. Use `theme` instead.',
      ),
      'target_access_levels?': type(type('10 | 15 | 20 | 30 | 40 | 50').array())
        .or('null')
        .describe(
          'Target access levels (roles) of the broadcast message. Possible values: `10` (Guest), `15` (Planner), `20` (Reporter), `30` (Developer), `40` (Maintainer), `50` (Owner).',
        ),
      'target_path?': type('string | null').describe('Target path of the broadcast message.'),
      'broadcast_type?': type("'banner' | 'notification' | null").describe(
        'Appearance type of the broadcast message.',
      ),
      'dismissable?': type('boolean | null').describe(
        'If `true`, the user can dismiss the message.',
      ),
      'theme?': type(
        "'indigo' | 'light-indigo' | 'blue' | 'light-blue' | 'green' | 'light-green' | 'red' | 'light-red' | 'dark' | 'light' | null",
      ).describe(
        'Color theme for the broadcast message. Applies only to banners. [Introduced](https://gitlab.com/gitlab-org/gitlab/-/issues/498900) in GitLab 17.6.',
      ),
    }),
  )
  .output(APIEntitiesSystemBroadcastMessageSchema)
  .handler(async ({ input }) => { throw new Error('Not implemented') })

